import { Effect, Option } from "effect"

type ReportOwner = {
  readonly id: string
  readonly email: string
  readonly notificationsEnabled: boolean
}

type CompletedReport = {
  readonly id: string
  readonly ownerId: string
  readonly downloadUrl: string
}

type Dependencies = {
  readonly findOwner: (
    ownerId: string
  ) => Effect.Effect<Option.Option<ReportOwner>>
  readonly recordDeliveryTarget: (
    reportId: string,
    ownerId: string
  ) => Effect.Effect<void>
  readonly sendEmail: (message: {
    readonly to: string
    readonly subject: string
    readonly downloadUrl: string
  }) => Effect.Effect<void>
}

export const notifyReportOwner = (
  report: CompletedReport,
  dependencies: Dependencies
) =>
  Effect.gen(function*() {
    const owner = yield* dependencies.findOwner(report.ownerId).pipe(
      Effect.map(Option.getOrUndefined)
    )

    if (owner !== undefined) {
      yield* dependencies.recordDeliveryTarget(report.id, owner.id)
    }

    if (owner !== undefined && owner.notificationsEnabled) {
      yield* dependencies.sendEmail({
        to: owner.email,
        subject: `Report ${report.id} is ready`,
        downloadUrl: report.downloadUrl
      })
    }
  })
